DROP TABLE IF EXISTS `BangGiaDichVu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `BangGiaDichVu` (
  `id` int NOT NULL AUTO_INCREMENT,
  `MaBangGia` varchar(20) NOT NULL,
  `dichVuId` int NOT NULL,
  `khuVucId` int DEFAULT NULL,
  `LoaiHinhDat` varchar(20) NOT NULL,
  `DonViTinh` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `DonGia` decimal(12,0) NOT NULL,
  `NgayApDung` date NOT NULL,
  `NgayKetThuc` date DEFAULT NULL,
  `TrangThai` varchar(20) NOT NULL DEFAULT 'DangApDung',
  `GiaCu` decimal(12,0) DEFAULT NULL COMMENT 'Giá cũ trước khi cập nhật. NULL nếu là bản ghi khởi tạo',
  `NguoiCapNhat` varchar(100) DEFAULT NULL COMMENT 'Người thực hiện thay đổi giá',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_BG_ma` (`MaBangGia`),
  KEY `idx_BangGia_DV` (`dichVuId`),
  KEY `idx_BangGia_KV` (`khuVucId`),
  CONSTRAINT `fk_BG_DV` FOREIGN KEY (`dichVuId`) REFERENCES `DichVu` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_BG_KV` FOREIGN KEY (`khuVucId`) REFERENCES `KhuVuc` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_BG_donGia` CHECK ((`DonGia` >= 0)),
  CONSTRAINT `chk_BG_giaCu` CHECK (((`GiaCu` is null) or (`GiaCu` >= 0))),
  CONSTRAINT `chk_BG_loai` CHECK ((`LoaiHinhDat` in (_utf8mb4'TheoLan',_utf8mb4'GoiThang'))),
  CONSTRAINT `chk_BG_ngay` CHECK (((`NgayKetThuc` is null) or (`NgayKetThuc` >= `NgayApDung`))),
  CONSTRAINT `chk_BG_trangThai` CHECK ((`TrangThai` in (_utf8mb4'DangApDung',_utf8mb4'HetHan')))
) ENGINE=InnoDB AUTO_INCREMENT=256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
